// 24×24 OpenAI blossom — 1-bit, rasterized from the official openai-blossom.svg
static const uint8_t kBlossom24[72] = {
  0x00, 0x00, 0x00,
  0x00, 0xFC, 0x00,
  0x03, 0x8F, 0xC0,
  0x03, 0x0F, 0xF0,
  0x06, 0x3C, 0x38,
  0x0C, 0x70, 0x18,
  0x3C, 0xC3, 0x8C,
  0x34, 0xCF, 0xEC,
  0x64, 0xFC, 0x7C,
  0x44, 0xFF, 0x1C,
  0x44, 0xC3, 0x8E,
  0x46, 0xC3, 0xE6,
  0x67, 0xC3, 0x62,
  0x71, 0xC3, 0x22,
  0x38, 0xFF, 0x22,
  0x3E, 0x3F, 0x26,
  0x37, 0xF3, 0x2C,
  0x31, 0xC3, 0x3C,
  0x18, 0x0E, 0x30,
  0x1C, 0x3C, 0x60,
  0x0F, 0xF0, 0xC0,
  0x03, 0xF1, 0xC0,
  0x00, 0x3F, 0x00,
  0x00, 0x00, 0x00,
};

static void drawBlossomIcon(int16_t x0, int16_t y0) {
#ifdef EPAPER_ENABLE
  for (int16_t y = 0; y < 24; y++) {
    for (int16_t x = 0; x < 24; x++) {
      size_t bit = (size_t)y * 24 + (size_t)x;
      if (kBlossom24[bit / 8] & (0x80 >> (bit % 8))) {
        epaper.drawPixel(x0 + x, y0 + y, TFT_BLACK);
      }
    }
  }
#endif
}

