// Ordered one-bit texture for secondary/history states. Density is deliberately
// limited to two levels: enough to create hierarchy on a monochrome panel,
// without turning small shapes into grey mush after an e-paper refresh.
static void fillDitherRect(int16_t x, int16_t y, int16_t w, int16_t h,
                           uint8_t density, uint16_t color = TFT_BLACK) {
#ifdef EPAPER_ENABLE
  if (w <= 0 || h <= 0 || density == 0) return;
  if (density > 2) density = 2;
  for (int16_t dy = 0; dy < h; dy++) {
    for (int16_t dx = 0; dx < w; dx++) {
      const bool ink = density == 1
                         ? ((dx + dy * 2) & 3) == 0       // 25%
                         : ((dx + dy) & 1) == 0;          // 50%
      if (ink) epaper.drawPixel(x + dx, y + dy, color);
    }
  }
#else
  (void)x; (void)y; (void)w; (void)h; (void)density; (void)color;
#endif
}

static void drawDashedHLine(int16_t x, int16_t y, int16_t w,
                            uint16_t color, int16_t dash = 5,
                            int16_t gap = 3) {
#ifdef EPAPER_ENABLE
  for (int16_t dx = 0; dx < w; dx += dash + gap) {
    const int16_t span = dx + dash <= w ? dash : w - dx;
    epaper.drawFastHLine(x + dx, y, span, color);
  }
#else
  (void)x; (void)y; (void)w; (void)color; (void)dash; (void)gap;
#endif
}

static void drawDashedVLine(int16_t x, int16_t y, int16_t h,
                            uint16_t color, int16_t dash = 5,
                            int16_t gap = 3) {
#ifdef EPAPER_ENABLE
  for (int16_t dy = 0; dy < h; dy += dash + gap) {
    const int16_t span = dy + dash <= h ? dash : h - dy;
    epaper.drawFastVLine(x, y + dy, span, color);
  }
#else
  (void)x; (void)y; (void)h; (void)color; (void)dash; (void)gap;
#endif
}

// Full-width physical-key strip. The three segments line up with the three
// page buttons and never imply touch interaction.
static void pageTabs(const char* current) {
#ifdef EPAPER_ENABLE
  static const char* kIds[3] = {"dash", "weather", "agenda"};
  static const char* kLabels[3] = {"1 USAGE", "2 WEATHER", "3 AGENDA"};
  static const int16_t kWidths[3] = {268, 252, 252};
  int16_t x = 14;
  const int16_t y = 438;
  const int16_t th = 33;
  epaper.setFreeFont(&FreeMono9pt7b);
  epaper.setTextDatum(MC_DATUM);
  for (uint8_t i = 0; i < 3; i++) {
    const int16_t tw = kWidths[i];
    bool active = current != nullptr && strcmp(current, kIds[i]) == 0;
    if (active) {
      epaper.fillRect(x, y, tw, th, TFT_BLACK);
      epaper.setTextColor(TFT_WHITE, TFT_BLACK);
    } else {
      epaper.drawRect(x, y, tw, th, TFT_BLACK);
      epaper.setTextColor(TFT_BLACK, TFT_WHITE);
    }
    epaper.drawString(kLabels[i], x + tw / 2, y + th / 2 + 1, GFXFF);
    x += tw;
  }
  epaper.setTextColor(TFT_BLACK, TFT_WHITE);
#endif
}

// Battery gauge: outline + nub, fill level = charge percent.
static void drawBatteryIcon(int16_t x, int16_t y, uint8_t pct,
                            uint16_t color = TFT_BLACK) {
#ifdef EPAPER_ENABLE
  epaper.drawRect(x, y, 18, 11, color);
  epaper.fillRect(x + 19, y + 3, 2, 5, color); // nub
  if (pct > 100) pct = 100;
  int16_t fill = (int16_t)((uint16_t)pct * 14 / 100);
  if (fill > 0) epaper.fillRect(x + 2, y + 2, fill, 7, color);
#endif
}

// Compact 1-bit Wi-Fi mark. Connected uses stepped arcs; disconnected keeps
// the same silhouette with a separated slash, so state is visible without
// relying on grey or a text label.
static void drawWifiIcon(int16_t x, int16_t y, bool connected,
                         uint16_t color = TFT_BLACK,
                         uint16_t background = TFT_WHITE) {
#ifdef EPAPER_ENABLE
  epaper.fillRect(x + 5, y, 6, 1, color);
  epaper.fillRect(x + 2, y + 1, 3, 1, color);
  epaper.fillRect(x + 11, y + 1, 3, 1, color);
  epaper.fillRect(x + 1, y + 2, 2, 1, color);
  epaper.fillRect(x + 13, y + 2, 2, 1, color);
  epaper.drawPixel(x, y + 3, color);
  epaper.drawPixel(x + 15, y + 3, color);

  epaper.fillRect(x + 6, y + 4, 4, 1, color);
  epaper.fillRect(x + 4, y + 5, 2, 1, color);
  epaper.fillRect(x + 10, y + 5, 2, 1, color);
  epaper.drawPixel(x + 3, y + 6, color);
  epaper.drawPixel(x + 12, y + 6, color);

  epaper.fillRect(x + 7, y + 7, 2, 1, color);
  epaper.drawPixel(x + 6, y + 8, color);
  epaper.drawPixel(x + 9, y + 8, color);
  epaper.fillRect(x + 7, y + 10, 2, 2, color);

  if (!connected) {
    // A 2 px core with a 1 px paper moat remains a slash at arm's length;
    // the old 1 px line broke the tiny arcs into what looked like panel noise.
    // Extend past the glyph so neither endpoint disappears into an arc.
    for (int16_t i = -2; i < 14; i++) {
      epaper.fillRect(x + 1 + i, y + i, 4, 1, background);
    }
    for (int16_t i = -2; i < 14; i++) {
      epaper.fillRect(x + 2 + i, y + i, 2, 1, color);
    }
  }
#endif
}

// ---------------------------------------------------------------------------
// Weather condition icons
//
// Solid silhouettes: at 20-36px on 1-bit e-paper a stroked glyph turns to
// noise, a filled shape stays legible from across a desk. (x, y) is the top
// left of an s-by-s box; the glyph centres itself inside it.
// ---------------------------------------------------------------------------
enum class WxIcon : uint8_t { NONE, SUN, PARTLY, CLOUD, RAIN, SNOW, STORM, FOG };

static WxIcon wxIconFor(const String& cond) {
  String s = cond;
  s.toLowerCase();
  if (s.indexOf("thunder") >= 0 || s.indexOf("storm") >= 0) return WxIcon::STORM;
  if (s.indexOf("snow") >= 0 || s.indexOf("sleet") >= 0) return WxIcon::SNOW;
  if (s.indexOf("rain") >= 0 || s.indexOf("drizzle") >= 0 || s.indexOf("shower") >= 0)
    return WxIcon::RAIN;
  if (s.indexOf("fog") >= 0 || s.indexOf("mist") >= 0 || s.indexOf("haze") >= 0)
    return WxIcon::FOG;
  if (s.indexOf("partly") >= 0 || s.indexOf("mainly") >= 0) return WxIcon::PARTLY;
  if (s.indexOf("cloud") >= 0 || s.indexOf("overcast") >= 0) return WxIcon::CLOUD;
  if (s.indexOf("clear") >= 0 || s.indexOf("sun") >= 0) return WxIcon::SUN;
  return WxIcon::NONE;
}

#ifdef EPAPER_ENABLE
static void wxSunDisc(int16_t cx, int16_t cy, int16_t s, uint16_t color) {
  const int16_t r = s * 22 / 100;
  const int16_t gap = r + s * 6 / 100; // where rays start
  const int16_t len = s * 14 / 100;    // ray length
  const int16_t th = s >= 30 ? 3 : 2;  // ray thickness
  epaper.fillCircle(cx, cy, r, color);
  epaper.fillRect(cx - th / 2, cy - gap - len, th, len, color); // N
  epaper.fillRect(cx - th / 2, cy + gap, th, len, color);       // S
  epaper.fillRect(cx - gap - len, cy - th / 2, len, th, color); // W
  epaper.fillRect(cx + gap, cy - th / 2, len, th, color);       // E
  // Diagonal rays: thickness-sized squares stepped along the 45° line.
  const int16_t d0 = (gap * 100 + 70) / 141;
  const int16_t dn = (len * 100 + 70) / 141;
  for (int16_t k = 0; k < dn; k++) {
    for (int8_t sx = -1; sx <= 1; sx += 2) {
      for (int8_t sy = -1; sy <= 1; sy += 2) {
        epaper.fillRect(cx + sx * (d0 + k) - th / 2, cy + sy * (d0 + k) - th / 2, th, th, color);
      }
    }
  }
}

static void wxCloudShape(int16_t cx, int16_t cy, int16_t s, uint16_t color) {
  // Two lobes over a rounded base; (cx, cy) is the base's centre.
  const int16_t base_w = s * 76 / 100;
  const int16_t base_h = s * 26 / 100;
  epaper.fillCircle(cx - base_w / 2 + base_h / 2 + s * 4 / 100, cy - s * 6 / 100, s * 16 / 100, color);
  epaper.fillCircle(cx + s * 6 / 100, cy - s * 14 / 100, s * 22 / 100, color);
  epaper.fillRoundRect(cx - base_w / 2, cy - base_h / 2, base_w, base_h, base_h / 2, color);
}

static void drawWeatherIcon(int16_t x, int16_t y, int16_t s, const String& cond,
                            uint16_t color = TFT_BLACK,
                            uint16_t background = TFT_WHITE) {
  const WxIcon icon = wxIconFor(cond);
  if (icon == WxIcon::NONE) return;
  const int16_t cx = x + s / 2;
  const int16_t cy = y + s / 2;
  switch (icon) {
    case WxIcon::SUN:
      wxSunDisc(cx, cy, s, color);
      break;
    case WxIcon::PARTLY: {
      // Sun peeking out top-right; an oversized white cloud first, so a
      // margin of paper separates the two shapes.
      wxSunDisc(cx + s * 18 / 100, cy - s * 18 / 100, s * 64 / 100, color);
      const int16_t ccx = cx - s * 4 / 100;
      const int16_t ccy = cy + s * 16 / 100;
      wxCloudShape(ccx, ccy, s * 116 / 100, background);
      wxCloudShape(ccx, ccy, s * 88 / 100, color);
      break;
    }
    case WxIcon::CLOUD:
      wxCloudShape(cx, cy + s * 6 / 100, s, color);
      break;
    case WxIcon::RAIN: {
      wxCloudShape(cx, cy - s * 12 / 100, s * 84 / 100, color);
      const int16_t drop = s * 16 / 100 < 4 ? 4 : s * 16 / 100;
      for (int8_t i = 0; i < 3; i++) {
        const int16_t dx = cx - s * 22 / 100 + i * (s * 22 / 100);
        const int16_t dy = cy + s * 10 / 100;
        for (int16_t k = 0; k < drop; k++) {
          epaper.fillRect(dx - k / 2, dy + k, 2, 2, color); // slanted drop
        }
      }
      break;
    }
    case WxIcon::SNOW: {
      wxCloudShape(cx, cy - s * 12 / 100, s * 84 / 100, color);
      for (int8_t i = 0; i < 3; i++) {
        const int16_t fx = cx - s * 22 / 100 + i * (s * 22 / 100);
        const int16_t fy = cy + s * 16 / 100 + (i == 1 ? s * 10 / 100 : 0);
        epaper.fillCircle(fx, fy, 2, color);
      }
      break;
    }
    case WxIcon::STORM: {
      wxCloudShape(cx, cy - s * 12 / 100, s * 84 / 100, color);
      // Bolt: a staircase of slabs stepping down-left, notched out of the
      // cloud by a white pass so the two shapes never merge into one blob.
      const int16_t bw = s * 18 / 100 < 4 ? 4 : s * 18 / 100;
      const int16_t step = s * 10 / 100 < 3 ? 3 : s * 10 / 100;
      const int16_t bx = cx + s * 2 / 100;
      const int16_t by = cy - s * 2 / 100;
      for (int8_t pass = 0; pass < 2; pass++) {
        const int16_t in = pass == 0 ? 2 : 0;
        const uint16_t pass_color = pass == 0 ? background : color;
        epaper.fillRect(bx - in, by - in, bw + 2 * in, step + 1 + 2 * in, pass_color);
        epaper.fillRect(bx - step / 2 - 1 - in, by + step - in, bw + 2 * in, step + 1 + 2 * in, pass_color);
        epaper.fillRect(bx - step - 2 - in, by + 2 * step - in, bw - 2 + 2 * in, step + 1 + 2 * in, pass_color);
      }
      break;
    }
    case WxIcon::FOG:
      wxCloudShape(cx, cy - s * 12 / 100, s * 84 / 100, color);
      epaper.fillRect(cx - s * 34 / 100, cy + s * 12 / 100, s * 68 / 100, 2, color);
      epaper.fillRect(cx - s * 26 / 100, cy + s * 22 / 100, s * 52 / 100, 2, color);
      break;
    default:
      break;
  }
}
#endif

static void header(const CardContent& c, const RenderStatus& st) {
#ifdef EPAPER_ENABLE
  // Blossom at left; date, Wi-Fi state, battery gauge and percentage at right.
  drawBlossomIcon(MARGIN, 8);
  epaper.setFreeFont(&FreeSans9pt7b);
  const String battery_pct = String(st.battery_pct) + "%";
  const int16_t battery_pct_w = epaper.textWidth(battery_pct, GFXFF);
  const int16_t battery_x = W - MARGIN - battery_pct_w - 4 - 21;
  const int16_t wifi_x = battery_x - 22;
  epaper.setTextDatum(TR_DATUM);
  if (c.header_date.length()) epaper.drawString(c.header_date, wifi_x - 4, 12, GFXFF);
  // Both icons and the percentage share the 9pt text midline.
  drawWifiIcon(wifi_x, 13, st.wifi_connected);
  drawBatteryIcon(battery_x, 13, st.battery_pct);
  epaper.drawString(battery_pct, W - MARGIN, 12, GFXFF);
  // brutalist hairline + 1px double-rule for density
  epaper.drawFastHLine(MARGIN, 42, W - 2 * MARGIN, TFT_BLACK);
  epaper.drawFastHLine(MARGIN, 44, W - 2 * MARGIN, TFT_BLACK);
#endif
}

// Payload strings are attacker-shaped as far as layout is concerned: nothing
// upstream bounds their length, drawString does not clip, and e-paper has no
// scroll. Trim to the space actually available, with an ellipsis so the reader
// can tell something was cut.
static String fit(const String& text, int16_t max_w) {
#ifdef EPAPER_ENABLE
  if (text.length() == 0 || epaper.textWidth(text, GFXFF) <= max_w) return text;
  // Plain ASCII: the GFX free fonts stop at 0x7E, so a U+2026 ellipsis would
  // render as nothing at all on the panel.
  const char* kCut = "...";
  int16_t budget = max_w - epaper.textWidth(kCut, GFXFF);
  if (budget <= 0) return kCut;

  // Longest prefix that fits, stepping only on UTF-8 character boundaries —
  // payloads carry multi-byte glyphs (the ° in every temperature) and half a
  // sequence is not valid text. Lengths here are tens of characters, so a
  // linear walk costs less than the string churn of a binary search.
  size_t n = text.length();
  while (n > 0) {
    while (n > 0 && ((uint8_t)text.charAt(n) & 0xC0) == 0x80) n--; // snap to boundary
    if (epaper.textWidth(text.substring(0, n), GFXFF) <= budget) break;
    n--;
  }
  return text.substring(0, n) + kCut;
#else
  (void)max_w;
  return text;
#endif
}

// The Usage page uses the compact, high-contrast status rail from the selected
// design. Keep the content payload human-readable ("Sunday, August 9") and
// abbreviate only at render time so the other cards can still use the full date.
static String compactDashDate(const String& raw) {
  String value = raw;
  value.trim();
  value.toUpperCase();
  int comma = value.indexOf(",");
  if (comma < 3) return value;

  String weekday = value.substring(0, 3);
  String rest = value.substring(comma + 1, value.length());
  rest.trim();
  int space = rest.indexOf(" ");
  if (space < 0) return weekday + " " + rest;

  String month = rest.substring(0, space);
  if (month.length() > 3) month = month.substring(0, 3);
  String day = rest.substring(space + 1, rest.length());
  day.trim();
  return weekday + " " + month + " " + day;
}

static String compactLastSync(const String& raw) {
  String value = raw;
  value.trim();
  value.toUpperCase();
  if (value.startsWith("LAST SYNC")) return value;

  // dash_sync historically sent "Wed 11:04 PM". Strip the weekday while
  // continuing to accept a bare "11:04 PM" from custom payload producers.
  int colon = value.indexOf(":");
  int space = value.indexOf(" ");
  if (colon >= 0 && space > 0 && space < colon && space <= 3) {
    value = value.substring(space + 1, value.length());
  }
  if (value.length() == 0) value = "--";
  return "LAST SYNC " + value;
}

static void terminalHeader(const char* page, const CardContent& c,
                           const RenderStatus& st) {
#ifdef EPAPER_ENABLE
  const int16_t rail_h = 31;
  epaper.fillRect(0, 0, W, rail_h, TFT_BLACK);
  epaper.setFreeFont(&FreeSans9pt7b);
  epaper.setTextColor(TFT_WHITE, TFT_BLACK);
  epaper.setTextDatum(TL_DATUM);
  String title = String("DEV DAY / ") + page;
  title.toUpperCase();
  epaper.drawString(title, 18, 6, GFXFF);

  const String battery_pct = String(st.battery_pct) + "%";
  const int16_t pct_right = W - 14;
  const int16_t pct_w = epaper.textWidth(battery_pct, GFXFF);
  const int16_t battery_x = pct_right - pct_w - 5 - 21;
  const int16_t wifi_x = battery_x - 26;
  drawWifiIcon(wifi_x, 8, st.wifi_connected, TFT_WHITE, TFT_BLACK);
  drawBatteryIcon(battery_x, 8, st.battery_pct, TFT_WHITE);
  epaper.setTextDatum(TR_DATUM);
  epaper.drawString(battery_pct, pct_right, 6, GFXFF);

  const String sync = compactLastSync(c.dash_insight_right);
  const int16_t sync_right = wifi_x - 12;
  epaper.drawString(sync, sync_right, 6, GFXFF);
  const int16_t date_right = sync_right - epaper.textWidth(sync, GFXFF) - 22;
  const String date = compactDashDate(c.header_date);
  if (date.length()) epaper.drawString(date, date_right, 6, GFXFF);

  epaper.setTextColor(TFT_BLACK, TFT_WHITE);
#endif
}

