static void drawDayChart(const CardContent& c, int16_t x, int16_t y,
                         int16_t w, int16_t h,
                         uint16_t color = TFT_BLACK) {
#ifdef EPAPER_ENABLE
  size_t n = c.dash_day_count;
  if (n == 0) {
    epaper.setFreeFont(&FreeSans9pt7b);
    epaper.setTextDatum(MC_DATUM);
    epaper.drawString("Plug in over USB to refresh activity", x + w / 2, y + h / 2, GFXFF);
    return;
  }
  if (n > CardContent::DASH_DAYS) n = CardContent::DASH_DAYS;

  const int16_t base_y = y + h - 1;
  const int16_t gap = 11;
  int16_t bar_w = (w - (int16_t)(n - 1) * gap) / (int16_t)n;
  if (bar_w < 4) bar_w = 4;

  uint8_t peak = 1;
  for (size_t i = 0; i < n; i++) {
    if (c.dash_day_tokens[i] > peak) peak = c.dash_day_tokens[i];
  }

  // Baseline rule the bars sit on.
  epaper.drawFastHLine(x, base_y, w, color);

  for (size_t i = 0; i < n; i++) {
    int16_t bh = (int16_t)((uint32_t)c.dash_day_tokens[i] * (uint32_t)(h - 2) / peak);
    if (c.dash_day_tokens[i] > 0 && bh < 3) bh = 3;
    int16_t bx = x + (int16_t)i * (bar_w + gap);
    int16_t by = base_y - bh;
    if (i + 1 == n) {
      epaper.fillRect(bx, by, bar_w, bh, color); // today: solid
    } else {
      const bool current_week = i + 7 >= n;
      epaper.drawRect(bx, by, bar_w, bh, color);
      fillDitherRect(bx + 1, by + 1, bar_w - 2, bh - 2,
                     current_week ? 2 : 1, color);
    }
  }
#endif
}

// First-boot splash: the Build Kit interior card, redrawn at panel scale.
// QR and wordmark up top, and the kit's face — a black dome rising from the
// bottom edge with plus-sign eyes — over the lower half. Pure geometry, so
// there is no bitmap to generate and nothing to alias.
static void renderSplash() {
#ifdef EPAPER_ENABLE
  // The same hardware-recipe QR the Yours page carries, centred like the card.
  const int16_t qr_scale = 3;
  drawQr((W - QR_RECIPE_SIZE * qr_scale) / 2, 36, qr_scale);

  epaper.setTextDatum(MC_DATUM);
  epaper.setFreeFont(&FreeSans12pt7b);
  epaper.drawString("OpenAI DevDay [2026]", W / 2, 184, GFXFF);
  epaper.setFreeFont(&FreeSans9pt7b);
  epaper.drawString("Dev Day Terminal", W / 2, 214, GFXFF);

  // The face takes the bottom half of the page: a circle centred on the
  // bottom edge, so exactly its top half shows.
  const int16_t R = H / 2;
  epaper.fillCircle(W / 2, H, R, TFT_BLACK);

  // Plus-sign eyes, measured off the card art: centres half a radius apart
  // (±0.50R), arm-to-stroke ratio 6.3, sitting 58% down the visible dome. The
  // card crops its circle 50px below centre where ours stops at centre, so
  // the vertical numbers scale from the visible dome height, not R.
  const int16_t eye_dx = 120;  // half the distance between eye centres
  const int16_t eye_y = H - R + 135;
  const int16_t arm = 96;      // full width/height of a plus
  const int16_t stroke = 15;
  for (int8_t side = -1; side <= 1; side += 2) {
    const int16_t ex = W / 2 + side * eye_dx;
    epaper.fillRect(ex - arm / 2, eye_y - stroke / 2, arm, stroke, TFT_WHITE);
    epaper.fillRect(ex - stroke / 2, eye_y - arm / 2, stroke, arm, TFT_WHITE);
  }
#endif
}

